const capitals = new Map([
  ["France", "Paris"],
  ["Peru", "Lima"],
  ["Kenya", "Nairobi"],
]);

console.log(`France: ${capitals.get("France")}`);

capitals.set("Japan", "Tokyo").set("Chile", "Santiago");
capitals.set("Kenya", capitals.get("Kenya").toUpperCase());
const removed = capitals.delete("Peru");

console.log(`Kenya: ${capitals.get("Kenya")}`);
console.log(`Deleted Peru: ${removed}`);
console.log(`Has Peru: ${capitals.has("Peru")}`);
console.log(`Spain: ${capitals.get("Spain")}`);
console.log(`Size: ${capitals.size}`);

capitals.clear();
console.log(`After clear: ${capitals.size}`);

