practice.solution:
const word = "mississippi";

const counts = new Map();

for (const ch of word) {
  counts.set(ch, (counts.get(ch) ?? 0) + 1);
}

counts.forEach((count, ch) => console.log(`${ch}: ${count}`));

console.log(`Letters: ${[...counts.keys()].join(", ")}`);

const sorted = [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
console.log("Sorted:");
for (const [ch, count] of sorted) {
  console.log(`${ch}: ${count}`);
}

example.code:
const obj = {};
obj[1] = "number";
obj["1"] = "string";

const map = new Map();
map.set(1, "number").set("1", "string");

console.log(`Object size: ${Object.keys(obj).length}`);
console.log(`Map size: ${map.size}`);
console.log(`obj[1]: ${obj[1]}`);
console.log(`map.get(1): ${map.get(1)}`);
console.log(`toString in {}: ${"toString" in {}}`);
console.log(`Map has toString: ${new Map().has("toString")}`);

const ada = { name: "Ada" };
const visits = new Map([[ada, 2]]);
console.log(`Same object: ${visits.get(ada)}`);
console.log(`Lookalike: ${visits.get({ name: "Ada" })}`);

const scores = new Map([["ada", 3], ["linus", 5]]);
console.log(`Wrong JSON: ${JSON.stringify(scores)}`);
console.log(`Right JSON: ${JSON.stringify(Object.fromEntries(scores))}`);

