practice.solution:
const flags = {};
const flagMap = new Map();

flags[true] = "boolean";
flags["true"] = "string";
flagMap.set(true, "boolean").set("true", "string");

const prices = { apple: 1.25, bread: 3.5 };

const priceMap = new Map(Object.entries(prices));

priceMap.set("milk", 2.75);

console.log(`Object size: ${Object.keys(flags).length}`);
console.log(`Map size: ${flagMap.size}`);
console.log(`flags[true]: ${flags[true]}`);
console.log(`flagMap.get(true): ${flagMap.get(true)}`);
console.log(`Price count: ${priceMap.size}`);

console.log(`JSON: ${JSON.stringify(Object.fromEntries(priceMap))}`);
